[
  {
    "qid": "0002-t2i-1",
    "sample_id": "0002_百内国家公园_478d0567.jpg",
    "task": "t2i",
    "knowledge_dim": "geo_landmark",
    "difficulty": "L2",
    "evidence_audit": {
      "visible_facts": [
        "画面远景为具有多个陡峭尖锐峰体的山地景观",
        "主峰岩壁呈深灰至暖褐色，局部高处覆盖白色积雪或冰雪",
        "前景有蓝绿色湍流水体穿过深色裸岩",
        "岸边为低矮灌木、草地和少量枯木，整体植被稀疏",
        "天空呈蓝紫至粉橙色渐变，具有日出或日落时段的光照效果"
      ],
      "anchor_features": [
        "百内国家公园最具识别性的百内塔山群",
        "三座高耸、陡直、彼此相邻的花岗岩塔状峰体",
        "巴塔哥尼亚荒野中的雪峰、裸岩、低矮植被与融水景观组合"
      ],
      "trigger_check": "能：提示词明确给出百内国家公园及其标志性主景，模型可凭该地标知识召回百内塔形制，并结合前景水景推断冰川融水的典型色泽。",
      "counterexample_test": "无法构造：在保持百内国家公园标志性主景为核心且符合该地理实体识别要求的前提下， generic 高山或透明深蓝水体会分别破坏地标身份与巴塔哥尼亚融水特征。"
    },
    "gen_prompt": "创作一幅电影感宽幅自然风光画：百内国家公园的清晨远景，标志性主景位于画面中上部，前景安排蜿蜒水景与深色岩岸，远处铺开荒野和低云；冷青与微暖晨光交织，写实摄影质感，细节清晰，但采用不同于样本的侧向视角。",
    "implicit_checks": [
      {
        "check": "百内塔以三座彼此相邻的高耸塔状峰体作为主要轮廓特征",
        "knowledge": "[solid] 百内国家公园的核心地标 Torres del Paine 由三座著名花岗岩塔峰构成，三峰组合是其最具识别性的外形特征。",
        "verified": true,
        "weight": 0.4,
        "rubric": {
          "0": "没有可辨认的百内塔山群，或只出现普通连绵山脉与圆钝山峰",
          "1": "出现尖锐高峰但数量、相邻关系或整体轮廓与百内塔山群不符",
          "2": "清楚呈现三座相邻且高耸陡直的塔状峰体，构成百内塔的核心轮廓"
        },
        "acceptable_variants": [
          "部分塔峰被云雾、逆光或前景遮挡，但仍能辨认三峰组合",
          "采用侧面或远距离视角，三座峰体的高度差与相邻关系仍然清楚"
        ]
      },
      {
        "check": "主要峰体呈垂直陡壁与尖锐塔状轮廓，裸露深色岩壁和高处白色覆盖物同时可见",
        "knowledge": "[solid] 百内塔为花岗岩侵入体经冰川和风化作用塑造的陡峭塔峰，垂直岩壁、尖锐峰顶及高处积雪或冰雪是其典型形态组合。",
        "verified": true,
        "weight": 0.3,
        "rubric": {
          "0": "峰体呈圆丘、缓坡或完整白色雪山，缺少陡直裸岩与尖锐塔状结构",
          "1": "峰体有陡峭岩壁或白色覆盖物之一，但另一项缺失或位置明显错误",
          "2": "峰体同时具备陡直裸露岩壁、尖锐塔状峰顶以及集中在高处的白色覆盖物"
        },
        "acceptable_variants": [
          "暖色侧光使岩壁呈红褐色或紫灰色，但裸岩与高处白色覆盖物的空间关系保持正确",
          "季节较暖时白色覆盖物较少，但仍保留局部高处雪线或冰雪残留"
        ]
      },
      {
        "check": "前景水体呈不透明的乳蓝、青绿色或灰蓝绿色，并具有融水浑浊感",
        "knowledge": "[solid] 巴塔哥尼亚高山水体常含冰川磨蚀产生的岩粉，悬浮颗粒会使融水呈乳蓝、青绿色或灰蓝绿色，而非完全透明的深蓝色。",
        "verified": true,
        "weight": 0.3,
        "rubric": {
          "0": "前景没有连续水体，或水体呈透明深蓝、黑色或明显不符合高山融水的颜色",
          "1": "水体带有蓝绿色但过于透明清澈，或颜色仅局部出现且缺少浑浊质感",
          "2": "前景水体整体呈乳蓝至青绿色，具有悬浮岩粉造成的不透明融水质感"
        },
        "acceptable_variants": [
          "在冷色晨光或阴天中呈灰蓝绿色，但仍保持不透明和含颗粒的视觉效果",
          "水流因长曝光呈柔滑带状，颜色与浑浊感仍然清楚可见"
        ]
      }
    ],
    "facet_tags": [
      "landmark_identity",
      "nature_morphology",
      "composition",
      "lighting_atmosphere"
    ],
    "gate_spec": {
      "required_subjects": [
        "百内国家公园",
        "百内塔"
      ],
      "theme_definition": "以百内国家公园标志性塔峰为核心的巴塔哥尼亚荒野风光场景"
    },
    "expected_failure_modes": [
      "将百内塔画成普通圆锥雪山或连续山脉，缺少三座相邻的垂直塔状峰体",
      "把主峰画成完全被冰雪覆盖的白色山体，缺少深色裸露岩壁和高处局部雪层",
      "将前景水体画成透明深蓝湖水，未呈现含冰川岩粉的乳蓝或青绿色融水质感"
    ],
    "notes": "利用百内塔的三峰形制与巴塔哥尼亚冰川融水色泽建立地标识别和自然形态知识探针。"
  }
]
